"use strict";(self["webpackChunkweb_tool_vue"]=self["webpackChunkweb_tool_vue"]||[]).push([[38807],{38807:function(n,e){const s='\n<div class="text-gray-700 leading-relaxed">\n  \x3c!-- 标题 --\x3e\n  <h1 class="text-3xl md:text-4xl font-bold text-gray-800 mb-6">别再手动整理了！一个工具帮你从大段文字中秒速找齐所有联系方式</h1>\n\n  \x3c!-- 引言 --\x3e\n  <p class="text-xl text-gray-600 mb-8">你是否也遇到过这种麻烦？一份长长的会议纪要、一篇产品介绍，或者是一大段微信聊天记录，里面散落着好几个手机号、邮箱和网页链接。你需要把它们一个个找出来，复制、粘贴到通讯录或Excel里，不仅费时费力，还容易看串行、漏掉信息。</p>\n  <p class="text-xl text-gray-600 mb-10">今天，就给大家介绍一个能帮你彻底告别这种繁琐工作的“数字小助手”——联系方式提取器。它的作用很简单：<strong>自动扫描文字，帮你把里面藏着的手机、邮箱和网址统统“揪”出来</strong>。</p>\n\n  \x3c!-- 什么是联系方式提取器 --\x3e\n  <section class="mb-10">\n    <h2 class="text-2xl font-semibold text-gray-800 mb-4 border-l-4 border-blue-500 pl-3">它能帮你做什么？</h2>\n    <p class="mb-4">你可以把它想象成一个眼神超好、手速超快的“信息侦察兵”。</p>\n    <ul class="space-y-3 pl-5 list-disc">\n      <li><span class="font-medium">整理客户资料：</span>从销售同事发来的项目文档里，一键提取所有客户的手机和邮箱。</li>\n      <li><span class="font-medium">汇总群聊信息：</span>在团队微信群或钉钉群里，快速收集大家留下的联系方式，不用再爬楼翻记录。</li>\n      <li><span class="font-medium">收集网页资源：</span>从一篇分享了很多参考文章链接的帖子中，瞬间把所有网址都整理出来。</li>\n      <li><span class="font-medium">处理简历信息：</span>收到多份简历文本，快速批量提取候选人的联系电话和邮箱地址。</li>\n    </ul>\n  </section>\n\n  \x3c!-- 核心功能介绍 --\x3e\n  <section class="mb-10">\n    <h2 class="text-2xl font-semibold text-gray-800 mb-4 border-l-4 border-green-500 pl-3">它能识别哪些信息？</h2>\n    <div class="grid md:grid-cols-3 gap-6 mb-6">\n      <div class="bg-blue-50 p-5 rounded-lg border border-blue-100">\n        <h3 class="font-bold text-blue-700 mb-2 flex items-center"><span class="inline-block w-3 h-3 rounded-full bg-blue-500 mr-2"></span>手机号码</h3>\n        <p class="text-sm">专门识别中国大陆常用的11位手机号，比如 13800138000。它会自动忽略那些长得像但不是手机号的数字组合。</p>\n      </div>\n      <div class="bg-green-50 p-5 rounded-lg border border-green-100">\n        <h3 class="font-bold text-green-700 mb-2 flex items-center"><span class="inline-block w-3 h-3 rounded-full bg-green-500 mr-2"></span>电子邮箱</h3>\n        <p class="text-sm">找出所有格式正确的邮箱地址，无论是公司邮箱（name@company.com）还是个人邮箱（abc123@gmail.com），都逃不过它的眼睛。</p>\n      </div>\n      <div class="bg-amber-50 p-5 rounded-lg border border-amber-100">\n        <h3 class="font-bold text-amber-700 mb-2 flex items-center"><span class="inline-block w-3 h-3 rounded-full bg-amber-500 mr-2"></span>网页链接</h3>\n        <p class="text-sm">识别以 “http://”、“https://” 或 “www.” 开头的网址，方便你快速收集文章、资料或产品页面的链接。</p>\n      </div>\n    </div>\n    <p class="text-gray-600 italic">你只需要把文字“喂”给它，剩下的事情它全包了。</p>\n  </section>\n\n  \x3c!-- 使用流程 --\x3e\n  <section class="mb-10">\n    <h2 class="text-2xl font-semibold text-gray-800 mb-4 border-l-4 border-purple-500 pl-3">怎么使用？简单三步</h2>\n    <div class="space-y-6">\n      <div class="flex items-start">\n        <div class="flex-shrink-0 w-8 h-8 rounded-full bg-blue-100 text-blue-800 font-bold flex items-center justify-center mr-4 mt-1">1</div>\n        <div>\n          <h4 class="font-medium text-gray-800 mb-1">粘贴你的文本</h4>\n          <p>无论是从Word、网页、聊天窗口还是PDF里复制的文字，都可以直接粘贴进页面的大输入框里。</p>\n        </div>\n      </div>\n      <div class="flex items-start">\n        <div class="flex-shrink-0 w-8 h-8 rounded-full bg-green-100 text-green-800 font-bold flex items-center justify-center mr-4 mt-1">2</div>\n        <div>\n          <h4 class="font-medium text-gray-800 mb-1">瞬间自动提取</h4>\n          <p>在你粘贴的瞬间，工具就已经在后台完成了扫描。右侧会立刻分门别类地显示出找到的所有手机、邮箱和链接，每种类型有多少个一目了然。</p>\n        </div>\n      </div>\n      <div class="flex items-start">\n        <div class="flex-shrink-0 w-8 h-8 rounded-full bg-amber-100 text-amber-800 font-bold flex items-center justify-center mr-4 mt-1">3</div>\n        <div>\n          <h4 class="font-medium text-gray-800 mb-1">勾选并一键复制</h4>\n          <p>你可以单独勾选需要的某个号码，也可以一键全选某一类（比如所有邮箱），甚至全选所有找到的信息。然后，点击“复制”按钮，所有被你选中的联系方式就会整整齐齐地保存到你的剪贴板，等着你粘贴到任何需要的地方了。</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  \x3c!-- 特色与好处 --\x3e\n  <section class="mb-10">\n    <h2 class="text-2xl font-semibold text-gray-800 mb-4 border-l-4 border-red-500 pl-3">为什么推荐它？</h2>\n    <div class="space-y-4">\n      <p><strong>彻底解放双手：</strong>告别用眼睛逐行扫描、用鼠标小心翼翼选择的原始方式。效率提升不止十倍。</p>\n      <p><strong>避免人为出错：</strong>机器识别精准，再也不会因为眼花而抄错一个数字，或者漏掉一个藏在角落的邮箱。</p>\n      <p><strong>批量操作超省心：</strong>处理成百上千字的文档时，批量全选、一键复制的功能显得尤为贴心。</p>\n      <p><strong>随时随地都能用：</strong>页面在手机和电脑上都能很好地显示和操作。在手机上，你可以直接复制微信聊天记录进行处理；在电脑上，则可以处理更大的文档。</p>\n      <p><strong>安全私密：</strong>整个过程都在你的浏览器本地完成，你粘贴的文字内容不会上传到任何服务器，不用担心信息泄露。</p>\n    </div>\n  </section>\n\n  \x3c!-- 总结 --\x3e\n  <section class="bg-gray-50 p-6 rounded-xl">\n    <h2 class="text-2xl font-semibold text-gray-800 mb-4">告别低效，开始高效整理</h2>\n    <p class="mb-4">时间应该花在更有价值的事情上，而不是浪费在重复机械的查找和复制中。</p>\n    <p class="mb-6">这个联系方式提取工具，就像给你的电脑或手机装上了一双“智能之眼”，专门帮你解决信息整理中最枯燥的那部分工作。无论你是行政、销售、人事，还是经常需要收集信息的学生或自由职业者，它都可能成为你的得力帮手。</p>\n    <p class="font-medium text-gray-800">下次再面对混杂着各种联系方式的文字时，不妨试试让它来帮你。你会发现，原来整理信息，也可以变得如此轻松简单。</p>\n  </section>\n</div>\n';e["default"]=s}}]);